raw.css:
:root{--color-bg:#fff8f0;--color-surface:#fff1df;--color-text:#3b2a1a;--color-border:#e0c9a6;--color-primary-dark:#7a3b12;--color-accent-on-dark:#f3c98b;--color-footer-bg:#3b2a1a;--font-base:Georgia, 'Times New Roman', serif;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--radius:0.5rem;--max-width:75rem;}
*{box-sizing:border-box;}
html,body{margin:0;padding:0;}
body{font-family:var(--font-base);background-color:var(--color-bg);color:var(--color-text);line-height:1.6;font-size:1rem;}
h1,h2,h3{line-height:1.2;margin-top:0;color:var(--color-text);}
p{margin-top:0;}
a{color:var(--color-primary-dark);text-decoration:underline;}
a:hover{text-decoration:none;}
a:focus,button:focus,input:focus,textarea:focus,select:focus{outline:3px solid var(--color-primary-dark);outline-offset:2px;}
.container{max-width:var(--max-width);margin:0 auto;padding:0 1rem;width:100%;}
header{background-color:var(--color-bg);border-bottom:1px solid var(--color-border);}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;padding-top:1rem;padding-bottom:1rem;gap:1rem;}
.logo{font-family:'Brush Script MT','Segoe Script',cursive;font-size:clamp(1.5rem,5vw,2rem);font-weight:400;color:var(--color-primary-dark);text-shadow:1px 1px 0 rgba(122,59,18,0.2);text-decoration:none;white-space:normal;word-break:break-word;}
.logo:hover{text-decoration:none;}
nav[aria-label='Main'] .nav-list{list-style:none;display:flex;flex-wrap:wrap;gap:1rem;margin:0;padding:0;}
nav[aria-label='Main'] a{text-decoration:none;color:var(--color-text);font-weight:bold;padding:0.5rem 0.25rem;}
nav[aria-label='Main'] a:hover{color:var(--color-primary-dark);text-decoration:underline;}
main{display:block;}
section{padding:var(--space-lg) 0;}
section:nth-of-type(even){background-color:var(--color-surface);}
.card{background-color:var(--color-bg);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);}
.grid{display:grid;gap:var(--space-md);grid-template-columns:1fr;}
.btn{display:inline-block;min-height:44px;padding:0.75rem 1.5rem;background-color:var(--color-primary-dark);color:#ffffff;border:none;border-radius:var(--radius);font-size:1rem;font-weight:bold;text-decoration:none;cursor:pointer;line-height:1.2;}
.btn:hover{background-color:#5c2c0d;}
form{display:flex;flex-direction:column;gap:var(--space-sm);max-width:36rem;}
.form-group{display:flex;flex-direction:column;gap:0.3rem;}
label{font-weight:bold;}
input,textarea,select{min-height:44px;padding:0.5rem 0.75rem;border:1px solid var(--color-border);border-radius:var(--radius);font-family:inherit;font-size:1rem;background-color:#ffffff;color:var(--color-text);}
textarea{min-height:8rem;resize:vertical;}
table{width:100%;border-collapse:collapse;}
table caption{text-align:left;font-weight:bold;margin-bottom:0.5rem;}
th,td{text-align:left;padding:0.6rem 0.8rem;border-bottom:1px solid var(--color-border);}
footer{background-color:var(--color-footer-bg);color:var(--color-accent-on-dark);padding:var(--space-md) 0;}
.footer-inner p{margin:0.2rem 0;}
.footer-name{font-weight:bold;font-size:1.1rem;}
.copyright{margin-top:0.6rem;font-size:0.85rem;opacity:0.9;}
@media (prefers-reduced-motion: reduce){*{animation:none !important;transition:none !important;}}
@media (max-width:600px){.header-inner{flex-direction:column;align-items:flex-start;}nav[aria-label='Main'] .nav-list{flex-direction:column;gap:0.5rem;width:100%;}section{padding:var(--space-md) 0;}.container{padding:0 0.75rem;}}
@media (min-width:601px){.grid-2{grid-template-columns:1fr 1fr;}.grid-3{grid-template-columns:repeat(3,1fr);}.header-inner{flex-wrap:nowrap;}}

